<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Gratitude.com — Activate Good</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Anton&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
  :root{
    --pink:#FE3184; --coral:#FF6B35; --orange:#ec7211;
    --grad: linear-gradient(135deg, var(--pink) 0%, var(--coral) 50%, var(--orange) 100%);
    --bg:#000; --card-top:#1a1a1a; --card-bot:#0d0d0d;
    --w100:rgba(255,255,255,1); --w80:rgba(255,255,255,.8); --w70:rgba(255,255,255,.7);
    --w60:rgba(255,255,255,.6); --w50:rgba(255,255,255,.5); --w40:rgba(255,255,255,.4);
    --border:rgba(255,255,255,.08); --border-hover:rgba(255,255,255,.15);
  }
  *{box-sizing:border-box; margin:0; padding:0;}
  body{background:var(--bg); font-family:'Inter',sans-serif; color:var(--w60); overflow-x:hidden;}
  h1,h2,h3{font-family:'Anton',sans-serif; font-weight:400; text-transform:uppercase; color:var(--w100); letter-spacing:-0.01em;}
  .container{max-width:1200px; margin:0 auto; padding:0 20px;}
  .label{font-size:14px; font-weight:400; letter-spacing:.1em; text-transform:uppercase; color:var(--pink); margin-bottom:16px;}
  .section{padding:96px 0;}
  a{text-decoration:none; color:inherit;}

  /* Buttons */
  .btn{display:inline-flex; align-items:center; justify-content:center; padding:1rem 2rem; border-radius:9999px; font-weight:600; font-size:16px; cursor:pointer; transition:all .3s ease; min-height:44px;}
  .btn-primary{background:var(--grad); color:#fff; box-shadow:0 10px 40px rgba(254,49,132,.3); border:none;}
  .btn-primary:hover{transform:translateY(-2px); box-shadow:0 15px 50px rgba(254,49,132,.4);}
  .btn-secondary{background:transparent; color:#fff; border:1px solid rgba(255,255,255,.2);}
  .btn-secondary:hover{background:rgba(255,255,255,.05); border-color:rgba(255,255,255,.4);}
  .cta-row{display:flex; gap:16px; flex-wrap:wrap;}

  /* Header */
  header.nav{position:sticky; top:0; z-index:20; background:rgba(0,0,0,.85); backdrop-filter:blur(10px); border-bottom:1px solid var(--border);}
  .nav-inner{display:flex; align-items:center; justify-content:space-between; padding:20px; max-width:1200px; margin:0 auto;}
  .wordmark{font-family:'Anton',sans-serif; font-size:20px; text-transform:uppercase; color:#fff; letter-spacing:.02em;}
  .nav-links{display:flex; gap:32px; font-size:14px; font-weight:500; color:var(--w70);}
  .nav-links a:hover{color:#fff;}

  /* Hero */
  .hero{position:relative; padding:140px 0 120px; overflow:hidden; text-align:center;}
  .glow-orb{position:absolute; border-radius:50%; filter:blur(90px); pointer-events:none;}
  .orb1{width:500px; height:500px; background:radial-gradient(circle, rgba(254,49,132,.35), transparent 70%); top:-200px; left:-100px;}
  .orb2{width:450px; height:450px; background:radial-gradient(circle, rgba(236,114,17,.3), transparent 70%); top:-100px; right:-150px;}
  .hero h1{font-size:clamp(40px,7vw,88px); line-height:.98; margin-bottom:24px;}
  .hero p{font-size:18px; line-height:1.7; color:var(--w60); max-width:600px; margin:0 auto 40px;}
  .hero .cta-row{justify-content:center;}

  /* Acts section */
  .acts-head{text-align:center; margin-bottom:56px;}
  .acts-head h2{font-size:clamp(32px,5vw,48px);}
  .sample-note{font-size:13px; color:var(--w40); margin-top:12px;}
  .card-grid{display:grid; grid-template-columns:repeat(3,1fr); gap:24px;}
  .card{position:relative; background:linear-gradient(180deg, var(--card-top) 0%, var(--card-bot) 100%); border:1px solid var(--border); border-radius:1rem; padding:2.5rem 2rem; overflow:hidden; transition:all .5s ease; cursor:pointer;}
  .card::before{content:''; position:absolute; top:-80px; left:-80px; width:160px; height:160px; border-radius:50%; background:linear-gradient(135deg, rgba(254,49,132,.4), rgba(236,114,17,.3)); filter:blur(48px); opacity:0; transition:opacity .7s ease;}
  .card::after{content:''; position:absolute; bottom:0; left:50%; transform:translateX(-50%) scaleX(0); width:100%; height:4px; background:var(--grad); transition:transform .5s ease;}
  .card:hover{transform:translateY(-8px); border-color:var(--border-hover); box-shadow:0 20px 60px rgba(0,0,0,.4), 0 0 80px rgba(254,49,132,.1), inset 0 0 0 1px rgba(254,49,132,.3);}
  .card:hover::before{opacity:1;}
  .card:hover::after{transform:translateX(-50%) scaleX(1);}
  .card:hover .card-text{color:var(--w80);}
  .card:hover .icon{transform:scale(1.1); border-color:rgba(254,49,132,.5); box-shadow:0 0 30px rgba(254,49,132,.3);}
  .icon{width:56px; height:56px; border-radius:12px; background:rgba(254,49,132,.1); border:1px solid rgba(254,49,132,.2); display:flex; align-items:center; justify-content:center; margin-bottom:20px; transition:all .5s ease; position:relative; z-index:1;}
  .icon svg{width:26px; height:26px; stroke:var(--pink); stroke-width:1.5; fill:none;}
  .card h3{font-size:20px; margin-bottom:10px; position:relative; z-index:1;}
  .card-text{font-size:15px; line-height:1.6; color:var(--w50); margin-bottom:20px; transition:color .3s ease; position:relative; z-index:1;}
  .badge{display:inline-flex; align-items:center; gap:6px; font-size:11px; font-weight:600; letter-spacing:.08em; text-transform:uppercase; color:var(--pink); background:rgba(254,49,132,.1); border:1px solid rgba(254,49,132,.2); border-radius:9999px; padding:5px 12px; margin-bottom:16px;}
  .badge-dot{width:6px; height:6px; border-radius:50%; background:var(--grad);}
  .sponsor{font-size:12px; color:var(--w40); margin-bottom:16px; position:relative; z-index:1;}
  .card-btn{width:100%; position:relative; z-index:1; padding:.85rem 1.5rem; font-size:14px;}

  /* How it works */
  .how{background:#0a0a0a; text-align:center;}
  .how-head{margin-bottom:64px;}
  .steps{display:grid; grid-template-columns:repeat(6,1fr); gap:20px;}
  .step{padding:12px;}
  .step-num{font-family:'Anton',sans-serif; font-size:40px; background:var(--grad); -webkit-background-clip:text; -webkit-text-fill-color:transparent; margin-bottom:8px;}
  .step h4{font-size:15px; text-transform:uppercase; color:#fff; margin-bottom:8px; letter-spacing:.02em;}
  .step p{font-size:13px; line-height:1.6; color:var(--w50);}

