  .final h2{font-size:clamp(32px,6vw,64px); margin-bottom:20px; position:relative;}
  .final p{font-size:18px; color:var(--w60); max-width:520px; margin:0 auto 40px; position:relative;}
  .final .cta-row{justify-content:center; position:relative;}

  /* Footer */
  footer{border-top:1px solid var(--border); padding:40px 0;}
  .footer-inner{display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:16px;}
  .footer-links{display:flex; gap:24px; font-size:13px; color:var(--w40);}
  .footer-links a:hover{color:var(--w70);}
  .copyright{font-size:13px; color:var(--w40);}

  /* Mobile */
  @media (max-width:640px){
    .section{padding:64px 0;}
    .hero{padding:100px 0 72px;}
    .nav-links{display:none;}
    .card-grid{grid-template-columns:1fr;}
    .steps{grid-template-columns:1fr 1fr; text-align:left;}
    .cta-row{flex-direction:column; width:100%;}
    .btn{width:100%;}
    .hero .cta-row, .final .cta-row{align-items:stretch;}
    .footer-inner{flex-direction:column; align-items:flex-start;}
  }
</style>
</head>
<body>

<header class="nav">
  <div class="nav-inner">
    <div class="wordmark">Gratitude</div>
    <nav class="nav-links">
      <a href="#acts">Activate</a>
      <a href="#final">Fund</a>
      <a href="#how">How it works</a>
    </nav>
  </div>
</header>

<section class="hero">
  <div class="glow-orb orb1"></div>
  <div class="glow-orb orb2"></div>
  <div class="container">
    <div class="label">Participant</div>
    <h1>Good is<br>ready to happen</h1>
    <p>Real acts of good are already funded. Choose one, and it moves. No payment, no wait, just a yes.</p>
    <div class="cta-row">
      <a class="btn btn-primary" href="#acts">Activate now</a>
      <a class="btn btn-secondary" href="#final">Fund more good</a>
    </div>
  </div>
</section>

<section class="section" id="acts">
  <div class="container">
    <div class="acts-head">
      <div class="label">Available now</div>
      <h2>Choose an act</h2>
      <p class="sample-note">Sample acts shown for illustration. Not live availability.</p>
    </div>
    <div class="card-grid">

      <div class="card">
        <div class="icon"><svg viewBox="0 0 24 24"><path d="M7 3v18M4 3v6a3 3 0 0 0 6 0V3M17 3v18M20 3c-2 1-3 3-3 6s1 5 3 6"/></svg></div>
        <span class="badge"><span class="badge-dot"></span>Funded and ready</span>
        <h3>A week of meals</h3>
        <p class="card-text">Deliver seven days of meals to a family through a trusted nonprofit partner.</p>
        <p class="sponsor">Made possible by [Sponsor]</p>
        <a class="btn btn-primary card-btn" href="#">Activate</a>
      </div>

      <div class="card">
        <div class="icon"><svg viewBox="0 0 24 24"><path d="M4 19V5a2 2 0 0 1 2-2h11l3 3v13a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2Z"/><path d="M8 7h8M8 11h8M8 15h5"/></svg></div>
        <span class="badge"><span class="badge-dot"></span>Funded and ready</span>
        <h3>School supplies for a classroom</h3>
        <p class="card-text">Equip a classroom with the supplies students need to start the year ready.</p>
        <a class="btn btn-primary card-btn" href="#">Activate</a>
      </div>

      <div class="card">
        <div class="icon"><svg viewBox="0 0 24 24"><path d="M3 11 12 3l9 8"/><path d="M5 10v10h14V10"/></svg></div>
        <span class="badge"><span class="badge-dot"></span>Funded and ready</span>
        <h3>A night of emergency shelter</h3>
        <p class="card-text">Provide a safe place to stay for someone facing an emergency tonight.</p>
        <p class="sponsor">Made possible by [Sponsor]</p>
        <a class="btn btn-primary card-btn" href="#">Activate</a>
      </div>

    </div>
  </div>
</section>

<section class="section how" id="how">
  <div class="container">
    <div class="how-head">
      <div class="label">The system</div>
      <h2>How it works</h2>
    </div>
    <div class="steps">
      <div class="step"><div class="step-num">1</div><h4>Pre-fund</h4><p>Capital is committed before the moment of action.</p></div>
      <div class="step"><div class="step-num">2</div><h4>Activate</h4><p>You choose an act. It costs nothing right now.</p></div>
      <div class="step"><div class="step-num">3</div><h4>Deliver</h4><p>A trusted nonprofit partner makes it real.</p></div>
      <div class="step"><div class="step-num">4</div><h4>Verify</h4><p>Delivery is confirmed, not assumed.</p></div>
      <div class="step"><div class="step-num">5</div><h4>Show impact</h4><p>You see what your choice made happen.</p></div>
      <div class="step"><div class="step-num">6</div><h4>Refill</h4><p>New funding makes more acts available.</p></div>
    </div>
  </div>
</section>

<section class="section final" id="final">
  <div class="glow-orb"></div>
  <div class="container">
    <div class="label">Your turn</div>
    <h2>There's more good waiting to happen</h2>
    <p>Most giving ends with a receipt. Gratitude ends with a result.</p>
    <div class="cta-row">
      <a class="btn btn-primary" href="#acts">Activate now</a>
      <a class="btn btn-secondary" href="#">Fund more good</a>
    </div>
  </div>
</section>

<footer>
  <div class="container footer-inner">
    <div class="wordmark" style="font-size:16px;">Gratitude</div>
    <div class="footer-links">
      <a href="#">About</a>
      <a href="#">Partners</a>
      <a href="#">Contact</a>
    </div>
    <div class="copyright">© 2026 Gratitude.com, Inc.</div>
  </div>
</footer>

</body>
</html>
```

